def expand(text: str) -> str:
    """Return the text with matching vocabulary appended, each addition separated by a comma so it is scored as its own phrase."""
    low = text.lower()
    extra = []
    for pat, add in RULES:
        if re.search(pat, low):
            extra.append(add)
    return text + (", " + ", ".join(extra) if extra else "")
